async function run() {
  const from = dates.startOfDay(now(), 0);
  const to = dates.startOfDay(now(), 1);

  const events = await calendar.events({ from, to });
  const sortedEvents = (events || []).slice().sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const agendaLines = sortedEvents.map(ev => {
    const isAllDay = typeof ev.start === 'string' && ev.start.length <= 10;
    const timeStr = isAllDay ? 'Dia todo' : dates.format(ev.start, 'HH:mm');
    return `• ${timeStr} ${ev.title}`;
  });

  const emails = await gmail.search({ query: 'in:inbox is:unread', unread: true, days: 1, max: 20 });

  const importantEmails = [];
  for (const e of emails || []) {
    const verdict = await judge.important(e);
    if (verdict && verdict.p >= 0.5) {
      importantEmails.push(e);
    }
  }

  const emailLines = importantEmails.map(e => `• ${e.from_name || e.from}: ${e.subject}`);

  const weather = await http.getJSON('https://api.open-meteo.com/v1/forecast?latitude=-23.55&longitude=-46.63&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=America%2FSao_Paulo&forecast_days=1');

  let weatherText = 'Tempo em São Paulo: indisponível no momento.';
  if (weather && weather.daily && weather.daily.temperature_2m_max && weather.daily.temperature_2m_max.length > 0) {
    const tmax = weather.daily.temperature_2m_max[0];
    const tmin = weather.daily.temperature_2m_min[0];
    const precip = weather.daily.precipitation_probability_max ? weather.daily.precipitation_probability_max[0] : null;
    weatherText = `Tempo em São Paulo: ${tmin}°C a ${tmax}°C` + (precip !== null && precip !== undefined ? `, ${precip}% de chance de chuva.` : '.');
  }

  const dayLabel = dates.format(now(), "EEEE', 'dd/MM");

  const agendaSection = agendaLines.length > 0 ? agendaLines.join('\n') : 'Nenhum evento hoje.';
  const emailSection = emailLines.length > 0 ? emailLines.join('\n') : 'Nenhum email importante.';

  const text = `Bom dia! Resumo de ${dayLabel}\n\nAgenda:\n${agendaSection}\n\nEmails importantes:\n${emailSection}\n\n${weatherText}`;

  log(text);
  await telegram.send({ text });
}

async function run() {
  const today = dates.today();
  const limit = dates.addDays(today, 7);

  const emails = await gmail.search({
    query: "boleto OR fatura OR invoice OR vencimento",
    days: 30,
    max: 30
  });

  const bills = [];
  for (const e of emails) {
    const text = `${e.subject} ${e.snippet}`;
    const due = dates.parse(text);
    if (!due) continue;
    // must be between today and today+7 (inclusive)
    if (dates.isBefore(due, today)) continue;
    if (dates.isBefore(limit, due)) continue;

    const amount = money.parse(text);
    if (amount === null) continue;

    bills.push({ due, amount, subject: e.subject, from_name: e.from_name });
  }

  if (bills.length === 0) {
    log("Nenhuma conta vencendo nos próximos 7 dias.");
    return;
  }

  bills.sort((a, b) => {
    if (dates.isBefore(a.due, b.due)) return -1;
    if (dates.isBefore(b.due, a.due)) return 1;
    return 0;
  });

  let total = 0;
  const lines = bills.map(b => {
    total += b.amount;
    return `• ${dates.format(b.due, "dd/MM")} — ${b.subject} (${b.from_name}): ${money.format(b.amount, "BRL")}`;
  });

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join("\n")}\n\nTotal: ${money.format(total, "BRL")}`;

  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({ query: "in:inbox is:unread", days: 2, unread: true, max: 50 });

  let archivedCount = 0;
  const archivedNames = [];

  for (const email of emails) {
    const result = await judge.newsletter(email);
    if (result.p >= 0.5) {
      await gmail.archive({ id: email.id });
      archivedCount++;
      archivedNames.push(email.from_name || email.from);
    }
  }

  let text;
  if (archivedCount === 0) {
    text = "Inbox cleanup done: no newsletters or promos to archive.";
  } else {
    const label = archivedCount === 1 ? "newsletter/promo" : "newsletters/promos";
    const names = archivedNames.length ? ` (${archivedNames.join(", ")})` : "";
    text = `Inbox cleanup done: archived ${archivedCount} ${label}${names}.`;
  }

  await telegram.send({ text });
}

async function run() {
  const bossEmail = "ana@acme.com";
  const notifiedLabel = "vigia/notified-ana";

  const results = await gmail.search({
    query: `in:inbox is:unread from:${bossEmail} -label:${notifiedLabel}`,
    days: 1,
    unread: true,
    max: 20
  });

  const toNotify = (results || []).filter(function (m) {
    const fromOk = (m.from || "").toLowerCase() === bossEmail.toLowerCase();
    const alreadyLabeled = (m.labels || []).some(function (l) {
      return l === notifiedLabel;
    });
    return fromOk && !alreadyLabeled;
  });

  for (const msg of toNotify) {
    const nameOrEmail = msg.from_name || msg.from;
    const subject = msg.subject || "(sem assunto)";
    const snippet = msg.snippet || "";
    const text = "📩 Email da " + nameOrEmail + ': "' + subject + '"' + (snippet ? "\n" + snippet : "");
    await telegram.send({ text: text });
    await gmail.label({ id: msg.id, label: notifiedLabel });
    log("Alerta enviado para email de " + nameOrEmail + " (" + msg.id + ")");
  }

  if (toNotify.length === 0) {
    log("Nenhum email novo e não lido de " + bossEmail + " no momento.");
  }
}

async function run() {
  const start = dates.addDays(dates.today(), 1);
  const end = dates.addDays(start, 7);
  const events = await calendar.events({ from: start, to: end });

  const days = [];
  for (let i = 0; i < 7; i++) {
    days.push(dates.addDays(start, i));
  }

  const lines = ["Your week ahead:"];
  for (const day of days) {
    const dayEvents = events.filter((e) => dates.sameDay(e.start, day));
    dayEvents.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

    lines.push("");
    lines.push(dates.format(day, "EEE dd/MM"));

    if (dayEvents.length === 0) {
      lines.push("• nothing scheduled");
    } else {
      for (const ev of dayEvents) {
        const hasTime = typeof ev.start === "string" && ev.start.includes("T");
        const label = hasTime
          ? dates.format(ev.start, "HH:mm") + " " + ev.title
          : ev.title;
        lines.push("• " + label);
      }
    }
  }

  const text = lines.join("\n");
  await telegram.send({ text });
  log("Sent weekly agenda covering " + events.length + " event(s)");
}

async function run() {
  const startDay = dates.addDays(dates.today(), 1); // tomorrow: start of the coming week
  const endExclusive = dates.addDays(startDay, 7);

  const events = await calendar.events({ from: startDay, to: endExclusive });

  const days = [];
  for (let i = 0; i < 7; i++) {
    days.push(dates.addDays(startDay, i));
  }

  const lines = ["Your week ahead:", ""];
  for (const day of days) {
    const label = dates.format(day, "EEE dd/MM");
    const dayEvents = events
      .filter(e => dates.sameDay(e.start, day))
      .sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

    lines.push(label);
    if (dayEvents.length === 0) {
      lines.push("• nothing scheduled");
    } else {
      for (const e of dayEvents) {
        const isAllDay = typeof e.start === "string" && e.start.length === 10;
        const time = isAllDay ? "All day" : dates.format(e.start, "HH:mm");
        lines.push(`• ${time} ${e.title}`);
      }
    }
    lines.push("");
  }

  while (lines.length && lines[lines.length - 1] === "") lines.pop();

  const text = lines.join("\n");
  log(text);
  await telegram.send({ text });
}

async function run() {
  function extractTrackingCode(text) {
    if (!text) return null;
    const specific = text.match(/(?:tracking number|tracking code|c[oó]digo de rastreio|c[oó]digo de rastreamento|rastreamento)[:\s]+([A-Za-z0-9]{6,20})/i);
    if (specific) return specific[1].toUpperCase();
    const generic = text.match(/\b(?=[A-Za-z0-9]{8,20}\b)(?=[A-Za-z0-9]*[A-Za-z])(?=[A-Za-z0-9]*\d)[A-Za-z0-9]{8,20}\b/);
    if (generic) return generic[0].toUpperCase();
    return null;
  }

  const query = 'tracking OR rastreio OR "código de rastreamento" OR shipped OR enviado';
  const emails = await gmail.search({ query, days: 14, max: 20 });

  const seen = new Set();
  const packages = [];

  for (const email of emails) {
    const text = `${email.subject || ''} ${email.snippet || ''}`;
    const code = extractTrackingCode(text);
    if (!code || seen.has(code)) continue;
    seen.add(code);
    packages.push({ code, email });
  }

  if (packages.length === 0) {
    log('No shipping notifications with tracking codes found today.');
    return;
  }

  const lines = [];
  for (const pkg of packages) {
    let info;
    try {
      info = await http.getJSON(`https://api.trackingmore.example/v1/track?code=${pkg.code}`);
    } catch (e) {
      log(`Failed to look up ${pkg.code}`);
      continue;
    }
    if (!info) continue;
    const statusLabel = (info.status || 'unknown').replace(/_/g, ' ');
    const sender = pkg.email.from_name || pkg.email.from || '';
    let line = `• ${pkg.code} (${sender}): ${statusLabel}`;
    if (info.last_event) line += ` — ${info.last_event}`;
    if (info.eta) line += `, ETA ${dates.format(info.eta, 'yyyy-MM-dd')}`;
    lines.push(line);
  }

  if (lines.length === 0) {
    log('No tracking info could be retrieved.');
    return;
  }

  const text = `📦 Package status\n\n${lines.join('\n')}`;
  await telegram.send({ text });
}

async function run() {
  const tomorrowStart = dates.startOfDay(now(), 1);
  const tomorrowEnd = dates.startOfDay(now(), 2);

  const events = await calendar.events({ from: tomorrowStart, to: tomorrowEnd });

  const withAttendees = (events || []).filter(e => Array.isArray(e.attendees) && e.attendees.length > 0);

  if (withAttendees.length === 0) {
    log("Nenhuma reunião com convidados amanhã.");
    return;
  }

  // Sort by start time to present in chronological order
  withAttendees.sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : 1));

  const blocks = [];

  for (const ev of withAttendees) {
    const timeLabel = dates.format(ev.start, "HH:mm");
    const lines = [`${timeLabel} ${ev.title}`];

    // dedupe attendee emails while preserving order
    const seen = new Set();
    const attendees = ev.attendees.filter(a => {
      if (!a || seen.has(a)) return false;
      seen.add(a);
      return true;
    });

    for (const email of attendees) {
      const results = await gmail.search({ query: `from:${email}`, days: 14, max: 5 });
      const items = results || [];
      const displayName = items.length > 0 ? items[0].from_name : email;

      if (items.length === 0) {
        lines.push(`• ${displayName} — sem emails recentes`);
      } else {
        const subjects = items.map(m => m.subject).filter(Boolean);
        lines.push(`• ${displayName} — ${subjects.join("; ")}`);
      }
    }

    blocks.push(lines.join("\n"));
  }

  const header = `Preparação para amanhã (${dates.format(tomorrowStart, "dd/MM")})`;
  const text = `${header}\n\n${blocks.join("\n\n")}`;

  await telegram.send({ text });
}

async function run() {
  const todayStart = dates.today();
  const tomorrowStart = dates.addDays(todayStart, 1);
  const dayAfter = dates.addDays(tomorrowStart, 1);

  const events = await calendar.events({ from: tomorrowStart, to: dayAfter });

  // keep only events that have at least one attendee, sorted by start time
  const meetings = (events || [])
    .filter(e => Array.isArray(e.attendees) && e.attendees.length > 0)
    .slice()
    .sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : 1));

  if (meetings.length === 0) {
    log('Nenhuma reunião de amanhã com convidados.');
    return;
  }

  // cache search results per attendee email so we don't repeat calls
  const emailCache = {};

  async function getAttendeeInfo(email) {
    if (emailCache[email]) return emailCache[email];
    const results = await gmail.search({ query: `from:${email}`, days: 14, max: 5 });
    let name = email;
    const subjects = [];
    if (Array.isArray(results)) {
      for (const r of results) {
        if (r.from_name) name = r.from_name;
        if (r.subject) subjects.push(r.subject);
      }
    }
    const info = { name, subjects };
    emailCache[email] = info;
    return info;
  }

  const blocks = [];

  for (const meeting of meetings) {
    const timeLabel = dates.format(meeting.start, 'HH:mm');
    const lines = [`${timeLabel} ${meeting.title}`];

    for (const email of meeting.attendees) {
      const info = await getAttendeeInfo(email);
      if (info.subjects.length > 0) {
        lines.push(`• ${info.name} — ${info.subjects.join('; ')}`);
      }
    }

    // only include the meeting block if we found at least one attendee with subjects,
    // otherwise still show the meeting header so it's not silently dropped
    blocks.push(lines.join('\n'));
  }

  const dateLabel = dates.format(tomorrowStart, 'dd/MM');
  const text = `Preparação para amanhã (${dateLabel})\n\n${blocks.join('\n\n')}`;

  await telegram.send({ text });
}

async function run() {
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);
  const rate = data && data.rates && data.rates.BRL;
  if (typeof rate !== "number") {
    log("No BRL rate found in response.");
    return;
  }
  const threshold = 5.40;
  log(`Current USD→BRL rate: ${rate}`);
  if (rate > threshold) {
    const text = `💵 USD→BRL is at ${rate.toFixed(2)}, above your ${threshold.toFixed(2)} threshold.`;
    await telegram.send({ text });
  } else {
    log(`Rate ${rate.toFixed(2)} is at or below threshold (${threshold.toFixed(2)}); no alert sent.`);
  }
}

async function run() {
  const cutoff = dates.addDays(now(), -3);
  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });

  const candidates = [];
  for (const e of emails) {
    if (e.replied) continue;
    if (!dates.isBefore(e.date, cutoff)) continue; // must be older than 3 days
    const { p } = await judge.needs_reply(e);
    if (p >= 0.5) candidates.push(e);
  }

  if (candidates.length === 0) {
    log("No emails waiting on reply for more than 3 days.");
    return;
  }

  candidates.sort((a, b) => (dates.isBefore(a.date, b.date) ? -1 : 1));

  const lines = candidates.map(
    (e) => `• ${e.from_name} — "${e.subject}" (since ${dates.format(e.date, "MMM d")})`
  );
  const text = `Waiting on your reply (3+ days):\n\n${lines.join("\n")}`;

  await telegram.send({ text });
}

async function run() {
  const todayStart = dates.startOfDay(now(), 0);
  const tomorrowStart = dates.startOfDay(now(), 1);
  const rangeEnd = dates.startOfDay(now(), 2);

  const events = await calendar.events({ from: todayStart, to: rangeEnd });

  const birthdays = (events || []).filter(e => e.calendar === "Birthdays");

  const todayList = [];
  const tomorrowList = [];

  for (const e of birthdays) {
    const name = e.title.replace(/^Anivers[áa]rio de\s*/i, "").trim() || e.title;
    if (dates.sameDay(e.start, todayStart)) {
      todayList.push(name);
    } else if (dates.sameDay(e.start, tomorrowStart)) {
      tomorrowList.push(name);
    }
  }

  if (todayList.length === 0 && tomorrowList.length === 0) {
    log("Nenhum aniversário hoje ou amanhã.");
    return;
  }

  const todayStr = dates.format(todayStart, "dd/MM");
  const tomorrowStr = dates.format(tomorrowStart, "dd/MM");

  let text = "🎂 Aniversários\n\n";
  if (todayList.length > 0) {
    text += `Hoje (${todayStr}): ${todayList.join(", ")}\n`;
  }
  if (tomorrowList.length > 0) {
    text += `Amanhã (${tomorrowStr}): ${tomorrowList.join(", ")}`;
  }

  await telegram.send({ text: text.trim() });
}
